import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.em2JOrjF.js";const p=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/index.md","filePath":"concepts/index.md"}'),n={name:"concepts/index.md"};function i(s,e,l,h,c,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>Every term VERA uses, in plain English. When something is referenced elsewhere in this documentation, it links back here.</p><hr><h2 id="a" tabindex="-1">A <a class="header-anchor" href="#a" aria-label="Permalink to &quot;A&quot;">​</a></h2><h3 id="allocation" tabindex="-1">Allocation <a class="header-anchor" href="#allocation" aria-label="Permalink to &quot;Allocation&quot;">​</a></h3><p>A per-person hour envelope on a project. When a Manager says &quot;give Alice 40 hours on the Nike project,&quot; that creates an allocation. See <a href="/vera-docs/concepts/allocations.html">Allocations &amp; Envelopes</a>.</p><h3 id="alert-threshold" tabindex="-1">Alert threshold <a class="header-anchor" href="#alert-threshold" aria-label="Permalink to &quot;Alert threshold&quot;">​</a></h3><p>The percentage of budget used that triggers a warning. Default is 80%. When a project reaches 80% of its hours budget, VERA flags it. Configurable per-project and per-task.</p><h3 id="agile-project" tabindex="-1">Agile project <a class="header-anchor" href="#agile-project" aria-label="Permalink to &quot;Agile project&quot;">​</a></h3><p>A project type made up of numbered sprints. The parent Agile project is a container — it has no contract value or budget of its own. Each sprint has its own contract value and hours budget. See <a href="/vera-docs/concepts/sprints.html">Agile &amp; Sprints</a>.</p><hr><h2 id="b" tabindex="-1">B <a class="header-anchor" href="#b" aria-label="Permalink to &quot;B&quot;">​</a></h2><h3 id="billing-rate" tabindex="-1">Billing rate <a class="header-anchor" href="#billing-rate" aria-label="Permalink to &quot;Billing rate&quot;">​</a></h3><p>The hourly rate charged to the client (revenue-side). Distinct from <code>hourly_cost</code>, which is what the agency pays the team member (cost-side). Set per-project in the Projects Master sheet. Owner-managed.</p><h3 id="budget-project-level" tabindex="-1">Budget (project-level) <a class="header-anchor" href="#budget-project-level" aria-label="Permalink to &quot;Budget (project-level)&quot;">​</a></h3><p>The total hours contracted or available for a project — <code>budget_hours</code> in the Projects sheet. Set by the Owner only. This is the Tier 1 budget. Not to be confused with allocations (Tier 2).</p><h3 id="burn-rate" tabindex="-1">Burn rate <a class="header-anchor" href="#burn-rate" aria-label="Permalink to &quot;Burn rate&quot;">​</a></h3><p>How fast a retainer is consuming its monthly hours budget. Expressed as a pace: hours logged ÷ days elapsed. VERA projects this forward to the end of the month and flags over/underpace. See <a href="/vera-docs/concepts/retainers.html#burn-rate">Retainers</a>.</p><hr><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h2><h3 id="client" tabindex="-1">Client <a class="header-anchor" href="#client" aria-label="Permalink to &quot;Client&quot;">​</a></h3><p>An organization or entity that work is done for. Every project must belong to a client. Internal overhead work uses the built-in &quot;Internal&quot; client.</p><h3 id="contract-value" tabindex="-1">Contract value <a class="header-anchor" href="#contract-value" aria-label="Permalink to &quot;Contract value&quot;">​</a></h3><p>The total dollar amount agreed with a client for a project (Fixed Price) or sprint (Agile). Used for revenue recognition — VERA calculates earned revenue as a percentage of completion against this value.</p><h3 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h3><p>What the agency pays to deliver the work. Calculated as <code>hours × hourly_cost</code> from Rate History. For vendor users with an active liability, the liability&#39;s <code>agreed_amount</code> overrides the hourly calculation entirely.</p><hr><h2 id="d" tabindex="-1">D <a class="header-anchor" href="#d" aria-label="Permalink to &quot;D&quot;">​</a></h2><h3 id="deadline" tabindex="-1">Deadline <a class="header-anchor" href="#deadline" aria-label="Permalink to &quot;Deadline&quot;">​</a></h3><p>The project delivery date. Visible to Owners and Managers. <strong>Never shown to Users.</strong> Not used for billing — it exists for capacity planning and delivery management.</p><h3 id="discipline" tabindex="-1">Discipline <a class="header-anchor" href="#discipline" aria-label="Permalink to &quot;Discipline&quot;">​</a></h3><p>A functional role category — e.g. Engineering, Design, Account Management. Used for capacity planning (<code>check_capacity</code>) and team categorisation. Separate from the user&#39;s permission role.</p><hr><h2 id="e" tabindex="-1">E <a class="header-anchor" href="#e" aria-label="Permalink to &quot;E&quot;">​</a></h2><h3 id="envelope" tabindex="-1">Envelope <a class="header-anchor" href="#envelope" aria-label="Permalink to &quot;Envelope&quot;">​</a></h3><p>Another word for an <a href="#allocation">allocation</a>. A per-person hour budget on a specific project. The name comes from the practice of putting a fixed amount of money in an envelope and distributing it — once it&#39;s spent, it&#39;s spent. See <a href="/vera-docs/concepts/allocations.html#what-is-an-envelope">Allocations &amp; Envelopes</a>.</p><hr><h2 id="f" tabindex="-1">F <a class="header-anchor" href="#f" aria-label="Permalink to &quot;F&quot;">​</a></h2><h3 id="fixed-price-project" tabindex="-1">Fixed Price project <a class="header-anchor" href="#fixed-price-project" aria-label="Permalink to &quot;Fixed Price project&quot;">​</a></h3><p>A project billed at a flat contract value regardless of hours. Revenue is recognised progressively: <code>(hours_logged ÷ hours_budget) × contract_value</code>. Work should stop when <code>hours_budget</code> is exhausted.</p><h3 id="forecast-allocation-aware" tabindex="-1">Forecast (allocation-aware) <a class="header-anchor" href="#forecast-allocation-aware" aria-label="Permalink to &quot;Forecast (allocation-aware)&quot;">​</a></h3><p>For retainers, VERA can project end-of-month hours two ways: (1) based on historical pace alone, or (2) <code>hours_logged + allocated_remaining</code> — the allocation-aware forecast, which accounts for scheduled work already planned. The allocation-aware forecast is more accurate when teams use allocations. See <a href="/vera-docs/concepts/retainers.html#allocation-aware-forecast">Retainers</a>.</p><hr><h2 id="h" tabindex="-1">H <a class="header-anchor" href="#h" aria-label="Permalink to &quot;H&quot;">​</a></h2><h3 id="health-status" tabindex="-1">Health status <a class="header-anchor" href="#health-status" aria-label="Permalink to &quot;Health status&quot;">​</a></h3><p>A project&#39;s overall delivery risk indicator. Computed from burn rate vs. budget:</p><ul><li><strong>Healthy</strong> (&gt;70% budget remaining) — ✅</li><li><strong>Watch</strong> (50–70% remaining) — ⚠️</li><li><strong>At Risk</strong> (&lt;50% remaining) — 🚨</li></ul><h3 id="hourly-cost" tabindex="-1">Hourly cost <a class="header-anchor" href="#hourly-cost" aria-label="Permalink to &quot;Hourly cost&quot;">​</a></h3><p>What the agency pays a team member per hour. Stored in Rate History with an effective date. Used to calculate project cost and margin. <strong>Owner-only data</strong> — never surfaced to Managers or Users.</p><hr><h2 id="l" tabindex="-1">L <a class="header-anchor" href="#l" aria-label="Permalink to &quot;L&quot;">​</a></h2><h3 id="liability" tabindex="-1">Liability <a class="header-anchor" href="#liability" aria-label="Permalink to &quot;Liability&quot;">​</a></h3><p>A fixed payment commitment to a vendor user on a project. Example: &quot;We agreed to pay Dev House X $5,000 for the auth module.&quot; When a liability exists, it replaces the hours × rate cost calculation for that vendor on that project. Create/cancel is Owner-only; read is Owner and Manager. See <a href="/vera-docs/concepts/vendors.html">Vendors &amp; Liabilities</a>.</p><hr><h2 id="m" tabindex="-1">M <a class="header-anchor" href="#m" aria-label="Permalink to &quot;M&quot;">​</a></h2><h3 id="manager" tabindex="-1">Manager <a class="header-anchor" href="#manager" aria-label="Permalink to &quot;Manager&quot;">​</a></h3><p>A permission role. Managers can see their assigned projects (percentages only, no dollar amounts), manage allocations for those projects, and approve time off. See <a href="/vera-docs/concepts/roles.html">Roles &amp; Permissions</a>.</p><h3 id="margin" tabindex="-1">Margin <a class="header-anchor" href="#margin" aria-label="Permalink to &quot;Margin&quot;">​</a></h3><p>Revenue minus cost for a project. <code>Margin = Revenue − Cost</code>. Shown as a dollar amount to Owners, or as a percentage to Managers.</p><hr><h2 id="o" tabindex="-1">O <a class="header-anchor" href="#o" aria-label="Permalink to &quot;O&quot;">​</a></h2><h3 id="out-of-office-ooo" tabindex="-1">Out of Office (OOO) <a class="header-anchor" href="#out-of-office-ooo" aria-label="Permalink to &quot;Out of Office (OOO)&quot;">​</a></h3><p>A protected project category (<code>time_off</code>) used to track employee absence. Users submit requests via <code>request_time_off</code>; Managers approve via <code>approve_time_off</code>. Time is only logged to OOO after approval — Users cannot log directly to the OOO project.</p><h3 id="owner" tabindex="-1">Owner <a class="header-anchor" href="#owner" aria-label="Permalink to &quot;Owner&quot;">​</a></h3><p>The highest permission role. Owners see everything: dollar amounts, rates, all projects, all users. See <a href="/vera-docs/concepts/roles.html">Roles &amp; Permissions</a>.</p><hr><h2 id="p" tabindex="-1">P <a class="header-anchor" href="#p" aria-label="Permalink to &quot;P&quot;">​</a></h2><h3 id="p-l-profit-loss" tabindex="-1">P&amp;L (Profit &amp; Loss) <a class="header-anchor" href="#p-l-profit-loss" aria-label="Permalink to &quot;P&amp;L (Profit &amp; Loss)&quot;">​</a></h3><p>Revenue minus cost, at the project or portfolio level. VERA calculates this live from time entries, rate history, and liabilities.</p><h3 id="pro-bono-project" tabindex="-1">Pro Bono project <a class="header-anchor" href="#pro-bono-project" aria-label="Permalink to &quot;Pro Bono project&quot;">​</a></h3><p>A project type with $0 revenue. Hours are tracked but no billing is generated. Useful for charity work, community projects, or internal initiatives that don&#39;t need financial tracking.</p><h3 id="project-master-22-projects-master" tabindex="-1">Project Master (22. Projects Master) <a class="header-anchor" href="#project-master-22-projects-master" aria-label="Permalink to &quot;Project Master (22. Projects Master)&quot;">​</a></h3><p>A sheet that stores financial metadata for each project: type, contract value, billing rate, is_billable. It&#39;s the source of truth for revenue calculations. Joined to the Projects sheet by project name.</p><h3 id="pto-paid-time-off" tabindex="-1">PTO (Paid Time Off) <a class="header-anchor" href="#pto-paid-time-off" aria-label="Permalink to &quot;PTO (Paid Time Off)&quot;">​</a></h3><p>Vacation or paid absence. Requested by Users, approved by Managers/Owners. The approval automatically logs the time entry. See <a href="/vera-docs/workflows/time-off.html">Time Off Requests</a>.</p><hr><h2 id="r" tabindex="-1">R <a class="header-anchor" href="#r" aria-label="Permalink to &quot;R&quot;">​</a></h2><h3 id="rate-history-13-rate-history" tabindex="-1">Rate History (13. Rate History) <a class="header-anchor" href="#rate-history-13-rate-history" aria-label="Permalink to &quot;Rate History (13. Rate History)&quot;">​</a></h3><p>An append-only ledger of hourly costs per team member. Each row has an <code>effective_from</code> date. When calculating cost for a past entry, VERA finds the rate that was effective on that entry&#39;s date. Changing a rate never alters historical data.</p><h3 id="retainer-project" tabindex="-1">Retainer project <a class="header-anchor" href="#retainer-project" aria-label="Permalink to &quot;Retainer project&quot;">​</a></h3><p>A project billed at a fixed monthly fee. The client pays for a set number of hours per month (<code>budget_hours</code>). VERA tracks monthly burn rate and flags over/underspend. See <a href="/vera-docs/concepts/retainers.html">Retainers</a>.</p><h3 id="revenue" tabindex="-1">Revenue <a class="header-anchor" href="#revenue" aria-label="Permalink to &quot;Revenue&quot;">​</a></h3><p>Money earned from a project. How it&#39;s calculated depends on project type — see <a href="/vera-docs/concepts/financials.html#revenue-by-project-type">Financials &amp; P&amp;L</a>.</p><h3 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h3><p>A user&#39;s permission level: <code>owner</code>, <code>manager</code>, or <code>user</code>. Controls what data they can see and what actions they can take. See <a href="/vera-docs/concepts/roles.html">Roles &amp; Permissions</a>.</p><hr><h2 id="s" tabindex="-1">S <a class="header-anchor" href="#s" aria-label="Permalink to &quot;S&quot;">​</a></h2><h3 id="sprint" tabindex="-1">Sprint <a class="header-anchor" href="#sprint" aria-label="Permalink to &quot;Sprint&quot;">​</a></h3><p>A time-boxed work unit within an <a href="#agile-project">Agile project</a>. Sprints have two statuses: <code>planned</code> ($0 revenue) and <code>active</code> (revenue accrues as hours are logged). Sprint numbers are auto-incremented. See <a href="/vera-docs/concepts/sprints.html">Agile &amp; Sprints</a>.</p><hr><h2 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to &quot;T&quot;">​</a></h2><h3 id="t-m-time-materials" tabindex="-1">T&amp;M (Time &amp; Materials) <a class="header-anchor" href="#t-m-time-materials" aria-label="Permalink to &quot;T&amp;M (Time &amp; Materials)&quot;">​</a></h3><p>A project type where the client is billed for actual hours worked at the billing rate. Revenue = <code>hours × billing_rate</code>. Work should stop when <code>hours_budget</code> is exhausted.</p><h3 id="task" tabindex="-1">Task <a class="header-anchor" href="#task" aria-label="Permalink to &quot;Task&quot;">​</a></h3><p>A work category used when logging time — e.g. Development, Design, QA, Client Meeting. Tasks must be enabled for a project before they can be used. Tasks can have their own hour budgets and alert thresholds.</p><h3 id="tenant" tabindex="-1">Tenant <a class="header-anchor" href="#tenant" aria-label="Permalink to &quot;Tenant&quot;">​</a></h3><p>A single workspace/client of the VERA platform. Each tenant has its own Slack app, Google Sheet, and credentials. Multi-tenant means one VERA deployment serves many agencies independently.</p><h3 id="time-entry" tabindex="-1">Time entry <a class="header-anchor" href="#time-entry" aria-label="Permalink to &quot;Time entry&quot;">​</a></h3><p>A single logged record of work: a person, a project, a task, hours, and a date. The atomic unit of all time tracking.</p><hr><h2 id="u" tabindex="-1">U <a class="header-anchor" href="#u" aria-label="Permalink to &quot;U&quot;">​</a></h2><h3 id="unresolved-item" tabindex="-1">Unresolved item <a class="header-anchor" href="#unresolved-item" aria-label="Permalink to &quot;Unresolved item&quot;">​</a></h3><p>A flagged operational issue that requires a Manager&#39;s attention — e.g. a team member is sick on a day they had active allocations, or someone was allocated beyond capacity. Shown in morning summaries as 🔴 blocks.</p><h3 id="user" tabindex="-1">User <a class="header-anchor" href="#user" aria-label="Permalink to &quot;User&quot;">​</a></h3><p>The base permission role. Users can log their own time, request time off, and view their own entries. See <a href="/vera-docs/concepts/roles.html">Roles &amp; Permissions</a>.</p><hr><h2 id="v" tabindex="-1">V <a class="header-anchor" href="#v" aria-label="Permalink to &quot;V&quot;">​</a></h2><h3 id="vendor" tabindex="-1">Vendor <a class="header-anchor" href="#vendor" aria-label="Permalink to &quot;Vendor&quot;">​</a></h3><p>A team member with <code>employment_type = &quot;vendor&quot;</code>. Represents an external contractor or agency. PMs log hours on behalf of vendors. Vendor cost is typically governed by a <a href="#liability">liability</a> rather than hourly rate.</p><h3 id="variance" tabindex="-1">Variance <a class="header-anchor" href="#variance" aria-label="Permalink to &quot;Variance&quot;">​</a></h3><p>The difference between planned and actual. Used in two contexts:</p><ul><li><strong>Hour variance</strong>: estimated hours − actual hours logged</li><li><strong>Cost variance</strong>: estimated cost − actual cost</li><li><strong>Burn rate variance</strong>: projected end-of-month hours − monthly budget (for retainers)</li></ul>',112)])])}const m=a(n,[["render",i]]);export{p as __pageData,m as default};
